window.RP_SESSION={"id":"S-77414dd1a89b","messages":[{"id":"RP-0112160","time":"2026-04-14T20:58:00+09:00","room":"RP","name":"엘런 파드메 / 서술","profile":"엘런 파드메","identity":"reviewed","type":"dialogue","body":"모험가.\n꿈을 좇아 자유로이 방랑하는 영혼.\n객기로 과대해석된 그저 그런 목숨을 쉬이 영혼길로 인도할 만큼의 위험이든, 돈방석 위 여인의 품 속에서 방탕하리만치 즐길 수 있을 나태한 평화든, 무엇이든 손 닿는 곳이라면 기꺼이 누릴 수 있는 그런 미래.\n\n수십수백, 어쩌면 그 이상일 지도 모를 모험가들에게 있어 모험의 의미는 필경 크게 다르지만은 않을 테다. 대대손손 배불리 먹일 수 있을 만큼의 권력과 부귀영화, 세계제일의 유명인이자 모험가 꿈나무 어린아이들의 우상, 추구하는 힘과 기술을 손에 넣음과 더불어 올라서게 될 정점의 강자, 그리고 수십의 미남 미녀들 사이에서 떵떵거리며 사랑을 속삭일 수 있는 대규모 하렘의 카사노바⋯⋯. 사실상 뻔하다. 그것들만큼 모험가들의 넘쳐나는 욕망을 양껏 자극하는 요소들은 몇 없을 테니까. 애시초 이미 널려있는 수많은 진부해빠진 직업과 진로들에게서 등을 돌리고 스스로 존망과 희비의 교차로 위로 기꺼이 발을 디디는 사람들에게 달리 무어 현실적인 고민이","characters":["P-78d86f34eb28"]},{"id":"RP-0112161","time":"2026-04-14T20:58:00+09:00","room":"RP","name":"엘런 파드메 / 서술","profile":"엘런 파드메","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-78d86f34eb28"]},{"id":"RP-0112162","time":"2026-04-14T20:58:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]}]};
